import fs from "node:fs";
import path from "node:path";
import dotenv from "dotenv";

export function loadStripeEnv() {
  dotenv.config({ path: path.resolve(process.cwd(), ".env"), quiet: true });
  dotenv.config({
    path: path.resolve(process.cwd(), ".env.local"),
    override: true,
    quiet: true,
  });
  // Use .env.example as fallback for values generated by scripts.
  dotenv.config({ path: path.resolve(process.cwd(), ".env.example"), quiet: true });
}

export function requireEnv(name) {
  const value = process.env[name];
  if (!value) {
    console.error(`Missing required env: ${name}`);
    process.exit(1);
  }
  return value;
}

export function upsertEnvFile(filePath, updates) {
  const absolute = path.resolve(process.cwd(), filePath);
  const existing = fs.existsSync(absolute) ? fs.readFileSync(absolute, "utf8") : "";
  const hasTrailingNewline = existing.endsWith("\n");
  const lines = existing.length > 0 ? existing.split(/\r?\n/) : [];

  for (const [key, value] of Object.entries(updates)) {
    const assignment = `${key}=${serializeEnvValue(value)}`;
    const index = lines.findIndex((line) => line.startsWith(`${key}=`));

    if (index >= 0) {
      lines[index] = assignment;
    } else {
      lines.push(assignment);
    }
  }

  const normalized = lines.filter((line, index) => !(line === "" && index === lines.length - 1));
  const output = normalized.join("\n") + (hasTrailingNewline || normalized.length > 0 ? "\n" : "");
  fs.writeFileSync(absolute, output, "utf8");
}

function serializeEnvValue(value) {
  const stringValue = String(value);

  // Keep plain values simple; quote values that contain spaces or JSON punctuation.
  if (/^[A-Za-z0-9._:/-]+$/.test(stringValue)) {
    return stringValue;
  }

  return `"${stringValue.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
}
